import{_ as e,o as i,c as n,a2 as o}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Planificación Académica: Proyecto Sociotecnológico II (Trimestre VI)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/Planificacion_Trimestre_II-VI.md","filePath":"materias/Proyecto_Sociotecnologico_II/Planificacion_Trimestre_II-VI.md"}'),r={name:"materias/Proyecto_Sociotecnologico_II/Planificacion_Trimestre_II-VI.md"};function c(t,a,l,s,d,u){return i(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="planificacion-academica-proyecto-sociotecnologico-ii-trimestre-vi" tabindex="-1">Planificación Académica: Proyecto Sociotecnológico II (Trimestre VI) <a class="header-anchor" href="#planificacion-academica-proyecto-sociotecnologico-ii-trimestre-vi" aria-label="Permalink to &quot;Planificación Académica: Proyecto Sociotecnológico II (Trimestre VI)&quot;">​</a></h1><p>El Trimestre VI es la etapa de consolidación, validación y entrega formal de la solución sociotecnológica. Los estudiantes realizan las pruebas de aseguramiento de calidad del software, ejecutan el plan de implantación en la comunidad, redactan los manuales técnicos/formativos y defienden su informe final ante la institución y la comunidad beneficiaria.</p><hr><h2 id="📅-trimestre-vi-pruebas-implantacion-manuales-y-socializacion-comunitaria-unidades-5-7-y-8" tabindex="-1">📅 Trimestre VI: Pruebas, Implantación, Manuales y Socialización Comunitaria (Unidades 5, 7 y 8) <a class="header-anchor" href="#📅-trimestre-vi-pruebas-implantacion-manuales-y-socializacion-comunitaria-unidades-5-7-y-8" aria-label="Permalink to &quot;📅 Trimestre VI: Pruebas, Implantación, Manuales y Socialización Comunitaria (Unidades 5, 7 y 8)&quot;">​</a></h2><h3 id="📝-evaluacion-1-planificacion-y-aplicacion-de-pruebas-de-software-unidad-5" tabindex="-1">📝 Evaluación 1: Planificación y Aplicación de Pruebas de Software (Unidad 5) <a class="header-anchor" href="#📝-evaluacion-1-planificacion-y-aplicacion-de-pruebas-de-software-unidad-5" aria-label="Permalink to &quot;📝 Evaluación 1: Planificación y Aplicación de Pruebas de Software (Unidad 5)&quot;">​</a></h3><p><strong>Objetivo:</strong> Garantizar la calidad, confiabilidad y robustez de la aplicación informática mediante pruebas formales.</p><ul><li>Fundamentos del aseguramiento de la calidad del software (QA).</li><li>Diseño y ejecución de casos de prueba: Pruebas de Caja Negra (funcionales, límites, valores nulos) y Pruebas de Caja Blanca.</li><li>Niveles de prueba: pruebas unitarias, de integración, de sistema y de regresión.</li><li>Matriz de control de pruebas y reporte de incidencias/corrección de errores críticos.</li><li><strong>Actividad:</strong> <strong>Dossier de Casos de Prueba y Reporte de Validación Funcional.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-estrategia-de-implantacion-y-capacitacion-a-usuarios-unidad-7" tabindex="-1">📝 Evaluación 2: Estrategia de Implantación y Capacitación a Usuarios (Unidad 7) <a class="header-anchor" href="#📝-evaluacion-2-estrategia-de-implantacion-y-capacitacion-a-usuarios-unidad-7" aria-label="Permalink to &quot;📝 Evaluación 2: Estrategia de Implantación y Capacitación a Usuarios (Unidad 7)&quot;">​</a></h3><p><strong>Objetivo:</strong> Poner en producción la aplicación en el entorno comunitario y transferir el conocimiento a los beneficiarios.</p><ul><li>Plan de implantación: despliegue en servidor local/nube, configuración del entorno operativo y migración de datos.</li><li>Pruebas de aceptación con usuarios finales (UAT) en el contexto real.</li><li>Diseño y ejecución del Plan de Capacitación / Alfabetización tecnológica para los operadores del sistema.</li><li>Acta de Entrega e Instalación y actas de asistencia a talleres formativos.</li><li><strong>Actividad:</strong> <strong>Informe de Implantación y Registro de Talleres de Capacitación.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-elaboracion-de-manuales-de-usuario-y-de-sistema-unidad-8" tabindex="-1">📝 Evaluación 3: Elaboración de Manuales de Usuario y de Sistema (Unidad 8) <a class="header-anchor" href="#📝-evaluacion-3-elaboracion-de-manuales-de-usuario-y-de-sistema-unidad-8" aria-label="Permalink to &quot;📝 Evaluación 3: Elaboración de Manuales de Usuario y de Sistema (Unidad 8)&quot;">​</a></h3><p><strong>Objetivo:</strong> Elaborar la documentación técnica y pedagógica que garantice la sostenibilidad y mantenimiento del sistema.</p><ul><li>Manual de Usuario: guía paso a paso, ilustrada con capturas de pantalla, orientada a operadores no técnicos.</li><li>Manual de Sistema / Instalación / Administrador: requerimientos de hardware/software, arquitectura, diagrama de despliegue, estructura del código fuente, diccionario de datos y procedimientos de respaldo/restauración de la base de datos.</li><li>Estándares de documentación técnica y licencias de software libre (GPL, Apache, Creative Commons).</li><li><strong>Actividad:</strong> <strong>Entrega formal de Manual de Usuario y Manual del Sistema.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-presentacion-y-defensa-del-proyecto-sociotecnologico-final-unidad-8" tabindex="-1">📝 Evaluación 4: Presentación y Defensa del Proyecto Sociotecnológico Final (Unidad 8) <a class="header-anchor" href="#📝-evaluacion-4-presentacion-y-defensa-del-proyecto-sociotecnologico-final-unidad-8" aria-label="Permalink to &quot;📝 Evaluación 4: Presentación y Defensa del Proyecto Sociotecnológico Final (Unidad 8)&quot;">​</a></h3><p><strong>Objetivo:</strong> Demostrar la solución integral desarrollada, sustentar metodológica y técnicamente el informe final y socializar los resultados.</p><ul><li>Estructura formal del Informe Final de Proyecto según la normativa vigente UPTT.</li><li>Portafolio de Evidencias: cartas de aceptación de la comunidad, minutas, firmas de 120 horas de labor comunitaria y fotografías.</li><li>Demostración integral en vivo del sistema en funcionamiento.</li><li>Socialización comunitaria y defensa pública ante jurado evaluador institucional.</li><li><strong>Actividad:</strong> <strong>Defensa Pública del Proyecto y Entrega del Informe Final Empastado/Digital.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al finalizar el Trayecto II, los estudiantes han completado el ciclo de vida completo de un software: desde el abordaje comunitario participativo y la especificación de requerimientos, hasta el modelado, codificación, pruebas rigurosas, implantación en producción, documentación exhaustiva y defensa socializada, obteniendo las competencias del nivel Técnico Superior Universitario (TSU) en Informática.</p>',19)])])}const f=e(r,[["render",c]]);export{p as __pageData,f as default};
